export type Segment = 'sme' | 'mid-corporate' | 'large-corporate';
export type DocumentKind = 'audited-financials' | 'board-resolution' | 'cash-flow-forecast' | 'collateral-schedule';

export interface RiskPolicy {
  minDscr: number;
  maxLeverage: number;
  requiredDocuments: readonly DocumentKind[];
}

/** Loaded from the risk policy config per segment - never hard-coded. */
export type RiskPolicyConfig = Readonly<Record<Segment, RiskPolicy>>;

export interface LoanApplication {
  applicationId: string;
  borrowerId: string;
  segment: Segment;
  facilityAmountUsd: number;
  documents: readonly DocumentKind[];
  netOperatingIncome: number;
  debtService: number;
  totalDebt: number;
  ebitda: number;
}

export type ScreeningResult = { status: 'clear' } | { status: 'potential-match'; listName: string };
export type ScreeningPort = (borrowerId: string) => ScreeningResult;

export interface AuditEntry {
  applicationId: string;
  check: string;
  inputs: Record<string, unknown>;
  threshold: string | null;
  outcome: 'pass' | 'flag';
  at: string;
  retentionYears: 7;
}

export interface ValidationResult {
  applicationId: string;
  status: 'clear' | 'exception';
  reasons: string[];
  missingDocuments: DocumentKind[];
  routedTo: 'credit-risk-officer' | null;
  fourEyesRequired: boolean;
}

export const FOUR_EYES_THRESHOLD_USD = 5_000_000;

const auditLog: AuditEntry[] = [];

function audit(entry: Omit<AuditEntry, 'retentionYears'>): void {
  auditLog.push({ ...entry, retentionYears: 7 });
}

export function checkDocuments(app: LoanApplication, policy: RiskPolicy): DocumentKind[] {
  return policy.requiredDocuments.filter((doc) => !app.documents.includes(doc));
}

export function evaluateRatios(app: LoanApplication, policy: RiskPolicy): string[] {
  const reasons: string[] = [];
  const dscr = app.netOperatingIncome / app.debtService;
  const leverage = app.totalDebt / app.ebitda;
  if (dscr < policy.minDscr) reasons.push('dscr-below-threshold');
  if (leverage > policy.maxLeverage) reasons.push('leverage-above-threshold');
  return reasons;
}

export function validateApplication(
  app: LoanApplication,
  policies: RiskPolicyConfig,
  screen: ScreeningPort,
  now: () => string = () => new Date().toISOString(),
): ValidationResult {
  const policy = policies[app.segment];
  const fourEyesRequired = app.facilityAmountUsd > FOUR_EYES_THRESHOLD_USD;
  const result: ValidationResult = {
    applicationId: app.applicationId,
    status: 'clear',
    reasons: [],
    missingDocuments: [],
    routedTo: null,
    fourEyesRequired,
  };

  const screening = screen(app.borrowerId);
  audit({ applicationId: app.applicationId, check: 'kyc-sanctions', inputs: { borrowerId: app.borrowerId },
    threshold: null, outcome: screening.status === 'clear' ? 'pass' : 'flag', at: now() });
  if (screening.status !== 'clear') {
    return { ...result, status: 'exception', reasons: ['sanctions-screening-hit'], routedTo: 'credit-risk-officer' };
  }

  const missing = checkDocuments(app, policy);
  audit({ applicationId: app.applicationId, check: 'document-completeness', inputs: { documents: app.documents },
    threshold: policy.requiredDocuments.join(','), outcome: missing.length === 0 ? 'pass' : 'flag', at: now() });
  if (missing.length > 0) {
    result.missingDocuments = missing;
    result.reasons.push('missing-documents');
  }

  const ratioReasons = evaluateRatios(app, policy);
  audit({ applicationId: app.applicationId, check: 'financial-ratios',
    inputs: { dscr: app.netOperatingIncome / app.debtService, leverage: app.totalDebt / app.ebitda },
    threshold: `dscr>=${policy.minDscr};leverage<=${policy.maxLeverage}`,
    outcome: ratioReasons.length === 0 ? 'pass' : 'flag', at: now() });
  result.reasons.push(...ratioReasons);

  if (result.reasons.length > 0) {
    // Never auto-reject: every exception goes to a credit risk officer with its reasons.
    result.status = 'exception';
    result.routedTo = 'credit-risk-officer';
  }
  return result;
}

export function recordDecision(
  applicationId: string,
  decision: 'approve' | 'decline' | 'refer',
  decidedBy: string,
  secondApprover: string | null,
  fourEyesRequired: boolean,
  at: string,
): { status: 201 } | { status: 422; reason: string } {
  if (fourEyesRequired && (secondApprover == null || secondApprover === decidedBy)) {
    return { status: 422, reason: 'four-eyes-required' };
  }
  audit({ applicationId, check: 'decision', inputs: { decision, decidedBy, secondApprover }, threshold: null,
    outcome: 'pass', at });
  return { status: 201 };
}

export function listAuditEntries(applicationId: string): AuditEntry[] {
  return auditLog.filter((e) => e.applicationId === applicationId).map((e) => ({ ...e }));
}

export function resetValidationState(): void {
  auditLog.length = 0;
}

