import assert from 'node:assert/strict';
import { beforeEach, test } from 'node:test';
import { listAuditEntries, recordDecision, resetValidationState, validateApplication } from '../src/loan-validation.ts';
import type { LoanApplication, RiskPolicyConfig, ScreeningPort } from '../src/loan-validation.ts';

const POLICIES: RiskPolicyConfig = {
  'sme': { minDscr: 1.25, maxLeverage: 3.5, requiredDocuments: ['audited-financials', 'cash-flow-forecast'] },
  'mid-corporate': { minDscr: 1.25, maxLeverage: 3.5, requiredDocuments: ['audited-financials', 'board-resolution'] },
  'large-corporate': { minDscr: 1.25, maxLeverage: 3.5, requiredDocuments: ['audited-financials', 'board-resolution', 'collateral-schedule'] },
};

const CLEAR: ScreeningPort = () => ({ status: 'clear' });
const NOW = () => '2026-10-05T10:00:00Z';

const APP: LoanApplication = {
  applicationId: 'app-1',
  borrowerId: 'borrower-a',
  segment: 'mid-corporate',
  facilityAmountUsd: 2_000_000,
  documents: ['audited-financials', 'board-resolution'],
  netOperatingIncome: 1_500_000,
  debtService: 1_000_000,
  totalDebt: 6_000_000,
  ebitda: 2_000_000,
};

beforeEach(() => {
  resetValidationState();
});

test('scenario: Incomplete application is flagged for missing documents', () => {
  const result = validateApplication({ ...APP, documents: [] }, POLICIES, CLEAR, NOW);
  assert.deepEqual(result.missingDocuments, ['audited-financials', 'board-resolution']);
  assert.equal(result.status, 'exception');
  assert.notEqual(result.status, 'rejected');
});

test('scenario: KYC or sanctions hit is routed to the credit risk officer', () => {
  const hit: ScreeningPort = () => ({ status: 'potential-match', listName: 'consolidated-sanctions' });
  const result = validateApplication(APP, POLICIES, hit, NOW);
  assert.deepEqual(result.reasons, ['sanctions-screening-hit']);
  assert.equal(result.routedTo, 'credit-risk-officer');
  assert.equal(listAuditEntries('app-1').length, 1);
});

test('scenario: Ratio breach is flagged against the risk policy thresholds', () => {
  const breach = { ...APP, netOperatingIncome: 1_100_000, totalDebt: 8_400_000 };
  const result = validateApplication(breach, POLICIES, CLEAR, NOW);
  assert.deepEqual(result.reasons, ['dscr-below-threshold', 'leverage-above-threshold']);

  const looser: RiskPolicyConfig = { ...POLICIES, 'mid-corporate': { ...POLICIES['mid-corporate'], maxLeverage: 4.5 } };
  const relaxed = validateApplication(breach, looser, CLEAR, NOW);
  assert.deepEqual(relaxed.reasons, ['dscr-below-threshold']);
});

test('scenario: Exceptions are routed, never auto-rejected, with four-eyes above USD 5M', () => {
  const large = { ...APP, facilityAmountUsd: 7_500_000, netOperatingIncome: 1_100_000 };
  const result = validateApplication(large, POLICIES, CLEAR, NOW);
  assert.equal(result.status, 'exception');
  assert.equal(result.routedTo, 'credit-risk-officer');
  assert.equal(result.fourEyesRequired, true);

  assert.deepEqual(recordDecision('app-1', 'approve', 'officer-1', null, true, NOW()), { status: 422, reason: 'four-eyes-required' });
  assert.deepEqual(recordDecision('app-1', 'approve', 'officer-1', 'officer-2', true, NOW()), { status: 201 });
});

test('scenario: Every check and decision is written to the audit log', () => {
  validateApplication(APP, POLICIES, CLEAR, NOW);
  recordDecision('app-1', 'approve', 'officer-1', null, false, NOW());

  const entries = listAuditEntries('app-1');
  assert.deepEqual(entries.map((e) => e.check), ['kyc-sanctions', 'document-completeness', 'financial-ratios', 'decision']);
  assert.ok(entries.every((e) => e.retentionYears === 7));
  assert.equal(entries[2].threshold, 'dscr>=1.25;leverage<=3.5');
});

